package com.termux.app.workspace;
import android.app.*;import android.os.Looper;import android.view.*;import android.widget.*;import com.termux.R;import com.termux.app.TermuxActivity;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class,instrumentedPackages={"com.termux.app.workspace.ProjectFiles"},shadows=AgentProjectFilesTabTest.Directory.class)
public class AgentProjectFilesTabTest {
 static int reads;static long modified;
 @Implements(value=ProjectFiles.class,isInAndroidSdk=false)public static class Directory{@Implementation protected ProjectFiles.Listing list(String path){reads++;ProjectFiles.Listing l=new ProjectFiles.Listing();l.path="/synthetic";l.entries.add(new ProjectFiles.Entry(l.path,"very long synthetic file name for small screens.txt",false,42,modified));l.entries.add(new ProjectFiles.Entry(l.path,"unknown.log",false,123));return l;}}
 boolean contains(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return true;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(contains(((ViewGroup)v).getChildAt(i),text))return true;return false;}
 void idle()throws Exception{for(int i=0;i<40;i++){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(5);}}
 void check(String agent)throws Exception{TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);a.setContentView(R.layout.activity_termux);WorkspaceLanguage.select(a,"ru");WorkspaceLanguage.apply(a);WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment=agent.equals("codex")?"codex":"ubuntu";p.claudeAgent=agent.equals("claude");p.geminiAgent=agent.equals("gemini");p.aiAgent=agent.equals("opencode")?"opencode":"";modified=java.time.Instant.parse("2026-11-04T12:42:08Z").toEpochMilli();reads=0;AgentProjectPanel.Chat chat=new AgentProjectPanel.Chat(){public boolean valid(){return true;}public List<JSONObject> rows(){fail("File tab must not read chat history");return null;}public boolean hasOlder(){return false;}public void older(){fail();}public void open(JSONObject f){fail();}public boolean jump(String k){return false;}public void observe(Runnable r){}public void close(){}};AgentProjectPanel.Backend backend=new AgentProjectPanel.Backend(){public byte[] read(String s,int n){fail("No Git or attachment request for Files");return null;}public void close(){}};WorkspaceFileBrowser browser=new WorkspaceFileBrowser(a,p,"/synthetic",null);browser.projectPanel=new AgentProjectPanel(a,p,"/synthetic",chat,backend);try{browser.show();idle();View root=a.findViewById(R.id.activity_termux_root_relative_layout).findViewWithTag("project-files-screen");assertNotNull(root);String first=new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm:ss",Locale.ROOT).format(new Date(modified));assertTrue(contains(root,first));assertTrue(contains(root,"Дата неизвестна"));assertNotNull(root.findViewWithTag("workspace-file-sort"));assertNotNull(root.findViewWithTag("project-tab-1"));int before=reads;modified+=1000;root.findViewWithTag("workspace-file-refresh").performClick();idle();assertTrue(reads>before);String next=new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm:ss",Locale.ROOT).format(new Date(modified));assertTrue(contains(root,next));root.measure(View.MeasureSpec.makeMeasureSpec(280,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY));root.layout(0,0,280,400);assertTrue(browser.projectPanel.content.getMeasuredHeight()>0);assertEquals(0,browser.projectPanel.selected);}finally{browser.close();a.finish();}}
 @Test public void codexRetainsRealFileBrowserDatesSortAndRefresh()throws Exception{check("codex");}
 @Test public void claudeRetainsRealFileBrowserDatesSortAndRefresh()throws Exception{check("claude");}
 @Test public void geminiRetainsRealFileBrowserDatesSortAndRefresh()throws Exception{check("gemini");}
 @Test public void openCodeRetainsRealFileBrowserDatesSortAndRefresh()throws Exception{check("opencode");}
}
